contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: deposit amount to fund c (sent from this contract), collect amount to withdraw
    function run(uint depositAmount, uint collectAmount) public payable {
        require(true);
        // Ensure this contract holds enough ETH to deposit into c when needed
        // If depositAmount > 0, we must have balance here to send
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "insufficient test balance");
            // Deposit into c (msg.sender for c will be this contract)
            c.Deposit{value: depositAmount}();
        }

        // Record balances before Collect
        uint beforeUserBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterUserBalance = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // If Collect succeeded (did not revert) then:
        // 1) the on-chain recorded user balance must have decreased by exactly collectAmount
        // 2) the contract's Ether balance must have decreased by at least collectAmount
        // We avoid underflow by writing comparisons that do not subtract when not safe.
        assert(
            reverted || (
                beforeUserBalance >= collectAmount &&
                // afterUserBalance equals beforeUserBalance - collectAmount
                afterUserBalance + collectAmount == beforeUserBalance &&
                // contract balance decreased by at least collectAmount
                beforeContractBalance >= afterContractBalance &&
                (beforeContractBalance - afterContractBalance) >= collectAmount
            )
        );
    }

    // allow receiving ETH so this test contract can be funded externally
    receive() external payable {}
}

