contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to deposit, amount to collect, and a minSum to set before initializing
    function run(uint depositAmt, uint collectAmt, uint minSum) public payable {
        require(address(this).balance >= depositAmt, "need deposit funds");

        // Ensure contract is configured: set MinSum and set log then initialize
        // These may revert if called twice, but we are first to call them.
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Read balances before any actions
        uint beforeBal = c.balances(address(this));
        uint beforeCBalance = address(c).balance;

        // Perform Deposit by sending Ether to c
        // ensure we have funds for the call
        c.Deposit{value: depositAmt}();

        uint afterDepositBal = c.balances(address(this));
        uint afterDepositCBalance = address(c).balance;

        // Now try Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalBal = c.balances(address(this));
        uint finalCBalance = address(c).balance;

        // General rule:
        // If Collect reverted then either recorded balance before Collect was < MinSum or < collectAmt.
        // If Collect returned then recorded balance decreased by at least collectAmt (i.e., finalBal <= afterDepositBal - collectAmt)
        // and contract's Ether balance decreased by at least collectAmt (finalCBalance <= afterDepositCBalance - collectAmt).
        // Express without underflow by rearranging inequalities.

        if (reverted) {
            // fetch MinSum and balances to assert condition
            uint observedMin = c.MinSum();
            // We assert that before attempting Collect (i.e., after deposit) either balance < MinSum or balance < collectAmt
            assert( (afterDepositBal < observedMin) || (afterDepositBal < collectAmt) );
        } else {
            // If it didn't revert: final recorded balance must be <= afterDepositBal and the decrease at least collectAmt
            // That is finalBal + collectAmt <= afterDepositBal  (avoids underflow)
            assert(finalBal + collectAmt <= afterDepositBal && finalCBalance + collectAmt <= afterDepositCBalance);
        }
    }

    // allow receiving ETH for funding deposits
    receive() external payable {}
}

