        } catch {
            collectReverted = true;
        }

        // Read final values after Collect attempt
        uint finalBal = c.balances(address(this));
        uint finalCbal = address(c).balance;

        // Read MinSum for use in the invariant
        uint observedMin = c.MinSum();

        // Single general assert describing the contract's required behavior for all inputs
        // If Collect reverted then (afterDepositBal < observedMin) || (afterDepositBal < collectAmt)
        // If Collect returned then finalBal + collectAmt <= afterDepositBal and finalCbal + collectAmt <= afterDepositCbal
        assert(
